<?php use Clinica\Services\MedicalValidator;use Clinica\Services\SessionService;
$base=$kind==='medico' ? '/medicos' : '/especialidades';$action=$editing ? $base.'/editar?id='.$id : $base.($kind==='medico' ? '/nuevo' : '/nueva');$cancel=$editing && $kind==='medico' ? '/medicos/detalle?id='.$id : $base;
?>
<div class="patient-page-heading"><div><span class="eyebrow text-secondary">MÉDICOS Y ESPECIALIDADES</span><h1><?= $escape($title) ?></h1><p class="text-secondary mb-0">Los campos marcados con * son obligatorios.</p></div><a class="btn btn-outline-secondary" href="<?= $escape($cancel) ?>">Cancelar</a></div>
<?php if(!$writesEnabled): ?><div class="alert alert-info" role="status">El guardado está temporalmente deshabilitado. Puede revisar el formulario sin cambiar los registros existentes.</div><?php endif; ?>
<?php if($errors): ?><div class="alert alert-danger" role="alert"><strong>No se guardaron cambios.</strong><ul class="mb-0"><?php foreach($errors as $message): ?><li><?= $escape($message) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="post" action="<?= $escape($action) ?>" class="patient-card patient-form" data-catalog-form>
<input type="hidden" name="csrf" value="<?= $escape(SessionService::csrf()) ?>"><?php if($editing): ?><input type="hidden" name="version" value="<?= $escape($version) ?>"><?php if($kind==='medico'): ?><input type="hidden" name="asociaciones_version" value="<?= $escape($associationVersion) ?>"><?php endif; ?><?php endif; ?>
<fieldset><legend><?= $kind==='medico' ? 'Datos del profesional' : 'Datos de la especialidad' ?></legend><div class="row g-4">
<?php foreach(MedicalValidator::fields($kind) as $field=>[$label,$max,$required]): $error=$errors[$field] ?? null; ?><div class="<?= $field==='descripcion' ? 'col-12' : 'col-md-6' ?>"><label class="form-label" for="<?= $field ?>"><?= $escape($label) ?><?= $required ? ' *' : '' ?></label>
<?php if($field==='estado'): ?><select name="estado" id="estado" required class="form-select <?= $error ? 'is-invalid' : '' ?>" <?= $error ? 'aria-invalid="true" aria-describedby="error-estado"' : '' ?>><?php foreach(['activo'=>'Activo','inactivo'=>'Inactivo'] as $state=>$labelState): ?><option value="<?= $state ?>" <?= ($values['estado'] ?? '')===$state ? 'selected' : '' ?>><?= $labelState ?></option><?php endforeach; ?></select>
<?php elseif($field==='descripcion'): ?><textarea name="descripcion" id="descripcion" rows="3" class="form-control <?= $error ? 'is-invalid' : '' ?>" <?= $error ? 'aria-invalid="true" aria-describedby="error-descripcion"' : '' ?>><?= $escape($values[$field] ?? '') ?></textarea>
<?php else: $type=$field==='correo_contacto' ? 'email' : ($field==='telefono' ? 'tel' : ($field==='precio_consulta' ? 'number' : 'text')); ?><input name="<?= $field ?>" id="<?= $field ?>" type="<?= $type ?>" class="form-control <?= $error ? 'is-invalid' : '' ?>" value="<?= $escape($values[$field] ?? '') ?>" <?= $required ? 'required' : '' ?> <?= $max!==null ? 'maxlength="'.$max.'"' : '' ?> <?= $field==='precio_consulta' ? 'min="0.01" max="9999999999.99" step="0.01" inputmode="decimal"' : '' ?> <?= $error ? 'aria-invalid="true" aria-describedby="error-'.$field.'"' : '' ?>><?php endif; ?>
<?php if($error): ?><div class="invalid-feedback" id="error-<?= $field ?>"><?= $escape($error) ?></div><?php endif; ?></div><?php endforeach; ?></div></fieldset>
<?php if($kind==='medico'): ?><fieldset><legend>Especialidades asociadas</legend><p class="text-secondary small">Seleccione las especialidades que corresponden al profesional. Las vinculadas a citas deben conservarse.</p><?php if(isset($errors['especialidades'])): ?><p class="text-danger" id="error-especialidades" role="alert"><?= $escape($errors['especialidades']) ?></p><?php endif; ?>
<div class="specialty-selection"><?php foreach($specialties as $e): $eid=(int)$e['id_especialidad'];$locked=in_array($eid,$protected,true); ?><div class="specialty-option"><input class="form-check-input" type="checkbox" id="specialty-<?= $eid ?>" name="especialidades[]" value="<?= $eid ?>" <?= in_array($eid,$selected,true) || $locked ? 'checked' : '' ?> <?= $locked ? 'disabled' : '' ?> <?= isset($errors['especialidades']) ? 'aria-describedby="error-especialidades"' : '' ?>><?php if($locked): ?><input type="hidden" name="especialidades[]" value="<?= $eid ?>"><?php endif; ?><label for="specialty-<?= $eid ?>"><?= $escape($e['nombre']) ?><small><?= $escape(ucfirst($e['estado'])) ?><?= $locked ? ' · Vinculada a citas' : '' ?></small></label></div><?php endforeach; ?></div><?php if(!$specialties): ?><p>No hay especialidades registradas.</p><?php endif; ?></fieldset><?php endif; ?>
<div class="patient-form-actions"><a class="btn btn-outline-secondary" href="<?= $escape($cancel) ?>">Cancelar</a><button type="submit" class="btn btn-clinic" <?= !$writesEnabled ? 'disabled' : '' ?>><?= $editing ? 'Guardar cambios' : 'Registrar' ?></button></div></form>
